Example:
Device(config-expression)# value type counter32

sample { absolute | delta | changed }
Example:
Device(config-expression-object)# sample delta

snmp-server view viewname oidtree { included | excluded }
Example:
Device(config)# snmp-server view view1 ipForward included

snmp mib target list vpnlistname { vrf vrfname | host ipaddress }
Example:
Device(config)# snmp mib target list commAVpn vrf vrf1

format { bulkBinary | bulkASCII | schemaASCII }
Example:
Device(config-bulk-tr)# format schemaASCII

version { 1 | 2 }
Example:
Device(config-router)# version 2

bba-group pppoe { name | global }
Example:
Device(config)# bba-group pppoe bba1

mpls label mode { vrf vrf-name | all-vrfs } protocol bgp-vpnv4 { per-prefix | per-vrf }
Example:
Device(config)# mpls label mode all-vrfs protocol bgp-vpnv4 per-vrf

mpls label mode { vrf vrf-name | all-vrfs } protocol { bgp-vpnv4 | bgp-vpnv6 | all-afs } { per-ce }
Example:
Device(config)# mpls label mode all-vrfs protocol bgp-vpnv6 per-ce

address-family { ipv4 | ipv6 }
Example:
Device(config-vrf) address-family ipv4

set extcommunity { rt extended-community-value [ additive ] | soo extended-community-value }
Example:
Device(config-route-map)# set extcommunity rt 100:4 additive

neighbor { ip-address | peer-group-name } route-map map-name { in | out }
Example:
Device(config-router-af)# neighbor 172.16.0.2 route-map extmap in

address-family { ipv4 | ipv6 }
Example:
Device(config-vrf) address-family ipv4

address-family { ipv4 | ipv6 }
Example:
Device(config-vrf) address-family ipv6

ipv6 address { ipv6-address / prefix-length | prefix-name sub-bits / prefix-length }
Example:
Device(config-if)# ipv6 address 2001:0DB8:0300:0201::/64
